	private static void applyRuntimeTelemetryMode(TupleExpr tupleExpr, RuntimeTelemetryMode runtimeTelemetryMode) {
		boolean enabled = runtimeTelemetryMode == RuntimeTelemetryMode.SAMPLED_FULL;
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				node.setRuntimeTelemetryEnabled(enabled);
				super.meetNode(node);
			}
		});
	}

	private static TupleExpr optimizeExactSequence(EvaluationStrategy strategy,
			SailDatasetTripleTermSource tripleSource,
			EvaluationStatistics statistics, TupleExpr tupleExpr, SailTupleQuery tupleQuery) {
		return new LmdbQueryOptimizerPipeline(strategy, tripleSource, statistics)
				.withPreparedQueryEntry(tupleExpr, tupleQuery.getActiveDataset(), tupleQuery.getBindings(),
						(prepared, cascades) -> {
							PhysicalProperties required = PhysicalProperties.builder()
									.boundVars(tupleQuery.getBindings().getBindingNames())
									.observationOrder(PhysicalProperties.ObservationOrder.EXACT_SEQUENCE)
									.build();
							OptimizationGoal goal = OptimizationGoal.root(prepared, required)
									.withInputBindingContext(
											InputBindingContext.fromBindingSet(tupleQuery.getBindings()));
							return cascades.planPreparedInput(prepared, goal).tupleExpr();
						});
	}

	public static <T> T withCascadesOptimizationTimeout(int maxExecutionTimeSeconds, Supplier<T> supplier) {
		if (maxExecutionTimeSeconds <= 0) {
			return supplier.get();
		}
		String previousValue = System.getProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY);
		long timeoutMillis = cascadesOptimizationTimeoutMillis(maxExecutionTimeSeconds, previousValue);
		System.setProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY, Long.toString(timeoutMillis));
		T result;
		try {
			result = supplier.get();
		} catch (RuntimeException | Error failure) {
			try {
				restoreCascadesOptimizationTimeout(previousValue);
			} catch (RuntimeException | Error cleanup) {
				if (cleanup != failure) {
					failure.addSuppressed(cleanup);
				}
			}
			throw failure;
		}
		restoreCascadesOptimizationTimeout(previousValue);
		return result;
	}

	static long cascadesOptimizationTimeoutMillis(int maxExecutionTimeSeconds, String currentValue) {
		long timeoutBudgetMillis = Math.max(1L,
				(maxExecutionTimeSeconds * MILLIS_PER_SECOND) / OPTIMIZATION_TIMEOUT_BUDGET_DIVISOR);
		if (currentValue == null || currentValue.isBlank()) {
			return timeoutBudgetMillis;
		}
		try {
			return Math.max(1L, Math.min(timeoutBudgetMillis, Long.parseLong(currentValue.trim())));
		} catch (NumberFormatException e) {
			return timeoutBudgetMillis;
		}
	}

	private static void restoreCascadesOptimizationTimeout(String previousValue) {
		if (previousValue == null) {
			System.clearProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY);
		} else {
			System.setProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY, previousValue);
		}
	}

	public CloseableIteration<BindingSet> evaluate() {
		NativeExecutionObservation.Capture capture = NativeExecutionObservation.current();
		CloseableIteration<BindingSet> result = evaluationStep.evaluate(EmptyBindingSet.getInstance());
		if (capture != null && capture.enabled()) {
			result = result instanceof CooperativeCancellation cancellation
					? new CooperativeObservedIteration(result, capture, cancellation)
					: new ObservedIteration(result, capture);
		}
		if (maxExecutionTimeSeconds > 0) {
			return new QueryInterruptIteration(result, 1000L * maxExecutionTimeSeconds);
		}
		return result;
	}

	/** Starts a bounded observation for this evaluation only; the snapshot is independent of the prepared plan. */
	public ObservedEvaluation evaluateObserved(int eventLimit, int labelCharacterLimit) {
		NativeExecutionObservation.Capture capture = NativeExecutionObservation.begin(eventLimit, labelCharacterLimit);
		try (var ignored = capture.enter()) {
			return new ObservedEvaluation(evaluate(), capture);
		}
	}

